class N191MemoryConsolidatorNode(BrainNode):
    """Node 191: 海马记忆回路·Encoder·ShortTerm·Episodic·Consolidator

    Folder: L07_Episodic--MemoryConsolidator
    Layer: L07
    Region: memory
    Responsibility: 记忆巩固器，短时转长时记忆
    """
    def process(self, data: BrainData) -> BrainData:
        """记忆巩固器，短时转长时记忆"""
        if isinstance(data, StateVector):
            arr = data.data.copy()
            # Memory encoding/retrieval with Hebbian-like update
            weights = self.get_state("weights")
            if weights is None:
                dim = len(arr)
                weights = np.random.randn(dim, dim).astype(np.float32) * 0.01
                self.set_state("weights", weights)
            result = arr @ weights
            # Normalize
            norm = np.linalg.norm(result)
            if norm > 0:
                result = result / norm * np.linalg.norm(arr)
            return StateVector(data=result.astype(np.float32), dimension=len(result))
        elif isinstance(data, Tensor):
            arr = data.data.copy()
            return Tensor(data=arr * self.get_state("gain", 1.0), shape=arr.shape)
        return data



